-- ============================================================
-- Quiz coverage for Phase 3 batch 7 (Cloud Strategy & Architecture --
-- Foundations & Security): cloud-fundamentals, multi-cloud,
-- networking-security, cloud-security. Covers overview/fundamentals/
-- intermediate for cloud-fundamentals and multi-cloud (no advanced
-- tab exists for either, confirmed via file listing), and overview/
-- fundamentals/intermediate/advanced for networking-security and
-- cloud-security (both have advanced tabs, confirmed via listing).
-- Interview/cheatsheets/notes/troubleshooting tabs are intentionally
-- not covered here, consistent with every prior Cloud batch's quiz
-- file (aws-identity-compute, azure-identity-compute).
-- ============================================================

INSERT INTO quiz_questions (academy_slug, technology_slug, section_slug, question, options, correct_index, explanation, difficulty) VALUES

-- ---------- cloud/cloud-fundamentals/overview ----------
('cloud', 'cloud-fundamentals', 'overview', 'What is the actual difference between hybrid cloud and multi-cloud?', '["They are the same thing, just different marketing terms", "Hybrid cloud connects one public cloud to your own on-premise infrastructure; multi-cloud uses multiple public cloud providers with no on-premise component required", "Hybrid cloud always means two public clouds; multi-cloud always means one public cloud plus on-premise", "Multi-cloud is only possible if the organization has no on-premise infrastructure at all"]', 1, 'Hybrid cloud specifically involves infrastructure you still physically operate (on-premise) connected to one public cloud; multi-cloud is entirely about using multiple public cloud vendors, with no on-premise component required.', 'beginner'),
('cloud', 'cloud-fundamentals', 'overview', 'Moving from IaaS to PaaS to SaaS, what changes along that spectrum?', '["Nothing meaningful changes; the terms are interchangeable", "How much of the stack you personally manage versus the provider manages -- you give up control as you move toward SaaS, in exchange for less operational burden", "Only the price changes; the management model stays identical", "SaaS always requires more hands-on infrastructure management than IaaS"]', 1, 'IaaS means you manage the OS upward; PaaS means you manage only your application code and data; SaaS means you just use finished software the provider manages entirely -- less control, less burden, moving in that direction.', 'beginner'),
('cloud', 'cloud-fundamentals', 'overview', 'Why is a single-AZ deployment, even with multiple redundant instances, not actually considered highly available?', '["Because AWS/Azure/GCP do not allow more than one instance per AZ", "Because all instances still share one failure domain -- if that single AZ (data center) fails, every instance fails with it, regardless of how many redundant instances exist within it", "Because single-AZ deployments are always more expensive than multi-AZ ones", "Because a single AZ can only run one instance type at a time"]', 1, 'True high availability requires spreading redundant instances across multiple, physically separate Availability Zones -- multiple instances confined to one AZ still share that AZ''s single point of failure.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'overview', 'What is the most defensible reason to adopt multi-cloud, according to this content?', '["\\"Just in case\\" -- multi-cloud should always be adopted as a general precaution", "A specific, named driver -- such as a regulatory data-residency requirement, a genuine best-of-breed service gap, or avoiding a critical single-vendor dependency for something business-critical", "Multi-cloud should be the default for every organization regardless of size", "Cost is always lower with multi-cloud, so it should always be adopted"]', 1, 'The content is explicit that multi-cloud adds real, ongoing operational complexity and should only be adopted for a specific, nameable strategic reason -- not as generic, undirected risk hedging.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'overview', 'On-premise infrastructure versus public cloud: what is the actual tradeoff, per this content?', '["Public cloud is unconditionally better in every scenario", "On-premise offers full control and can be cheaper at large, stable, predictable scale, but requires large upfront capital investment and multi-year hardware refresh cycles; cloud trades that for elasticity and variable cost", "On-premise is always cheaper than cloud regardless of scale", "There is no meaningful cost difference between the two approaches"]', 1, 'The right choice depends on workload predictability, existing capital investment, compliance constraints, and team expertise -- not a blanket rule that one is always superior.', 'advanced'),

-- ---------- cloud/cloud-fundamentals/fundamentals ----------
('cloud', 'cloud-fundamentals', 'fundamentals', 'In the shared responsibility model, which security area remains YOUR responsibility across IaaS, PaaS, and SaaS alike?', '["Physical data center security", "Hypervisor and hardware maintenance", "Application security, data encryption, and IAM configuration", "None -- the provider is responsible for all of it in every service model"]', 2, 'The line between provider and customer responsibility moves up the stack as you go from IaaS to SaaS, but application security, data encryption, and IAM configuration remain the customer''s responsibility at every layer.', 'beginner'),
('cloud', 'cloud-fundamentals', 'fundamentals', 'What do the largest publicized cloud breaches (Capital One, Twitch, Toyota, per this content) have in common?', '["They were all caused by a flaw in the cloud provider''s own infrastructure", "They were customer-side misconfigurations -- public S3 buckets, overly permissive IAM roles, internet-accessible databases -- not cloud provider failures", "They all happened because the customer chose the wrong cloud provider", "None of them involved any IAM or access-control issue"]', 1, 'This content explicitly frames these as misconfigurations, not provider infrastructure failures -- the practical argument for taking the shared responsibility model seriously.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'fundamentals', 'What is the key distinguishing feature of the event-driven architecture pattern?', '["Services communicate exclusively through direct, synchronous API calls", "Services communicate via events on a queue/bus (SQS, Pub/Sub, EventBridge) rather than direct calls, decoupling producers from consumers", "It requires every service to share the same database", "It is only usable within a single cloud provider, never across providers"]', 1, 'Event-driven architecture decouples producers from consumers by routing communication through a queue or event bus, rather than direct service-to-service calls.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'fundamentals', 'What is the practical difference between "scalable" and a cloud-native, fully "automated" deployment approach, per the Traditional vs. Cloud-Native comparison?', '["There is no difference between traditional and cloud-native approaches", "Traditional infrastructure typically involves manual config and manual deploys with infrequent releases; cloud-native uses IaC + GitOps for frequent, automated deployments and treats failure as expected, not exceptional", "Cloud-native systems never fail, unlike traditional systems", "Traditional infrastructure always scales horizontally, while cloud-native scales vertically"]', 1, 'The comparison table contrasts manual, infrequent, vertically-scaled traditional deployments against automated, frequent, horizontally-scaled, failure-expecting cloud-native ones.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'fundamentals', 'If an S3 bucket is configured with public read access and sensitive data leaks as a result, whose responsibility is that under the shared responsibility model?', '["AWS''s responsibility, since S3 itself was involved", "Entirely the customer''s responsibility -- AWS kept the S3 service itself unbreached; the customer misconfigured the access setting on it", "Shared 50/50 between AWS and the customer automatically", "Nobody''s responsibility, since cloud storage is inherently insecure"]', 1, 'This is the concrete example the content uses to illustrate the shared responsibility model in practice -- the provider secured the service; the customer''s own configuration caused the exposure.', 'beginner'),

-- ---------- cloud/cloud-fundamentals/intermediate ----------
('cloud', 'cloud-fundamentals', 'intermediate', 'What is the precise difference between RTO and RPO?', '["They both measure the exact same thing", "RTO is how long you can tolerate being down before service is restored; RPO is how much data loss (measured in time) is acceptable", "RTO measures data loss; RPO measures downtime", "RPO only applies to on-premise systems, never cloud systems"]', 1, 'RTO (Recovery Time Objective) governs acceptable downtime; RPO (Recovery Point Objective) governs acceptable data loss -- the two drive genuinely different architectural decisions.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'intermediate', 'What is the real, practical difference between "scalability" and "elasticity"?', '["They are exactly the same concept with two different names", "Scalability is the capability to handle more load by adding resources; elasticity is automatically scaling up AND back down in response to real demand, without manual intervention", "Elasticity only refers to scaling down, never scaling up", "Scalability requires cloud infrastructure; elasticity does not"]', 1, 'A system can be scalable (you can manually add servers) without being elastic (nothing does that automatically) -- cloud''s actual cost advantage comes specifically from elasticity''s automatic scale-down.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'intermediate', 'Why are Reserved/committed-use pricing discounts inappropriate for a workload still finding its real steady-state size?', '["Reserved pricing is always more expensive than on-demand, regardless of workload maturity", "Reserved/committed pricing requires committing to a usage baseline for 1-3 years -- locking in a size before it's actually known wastes the discount or creates a costly mismatch", "Reserved instances cannot be used for any workload under active development", "Reserved pricing is only available for storage, never compute"]', 1, 'Committed-use discounts make sense specifically for stable, predictable workloads -- committing before the real steady-state size is known risks over- or under-provisioning against that commitment.', 'advanced'),
('cloud', 'cloud-fundamentals', 'intermediate', 'For a simple, stateless, short-duration API, what commonly rules out FaaS/serverless as the right choice?', '["FaaS cannot be used for APIs at all", "Most FaaS execution environments impose a hard duration limit (commonly cited around 15 minutes for AWS Lambda), which rules FaaS out for long-running or genuinely stateful requirements", "FaaS is always more expensive than IaaS for any workload", "FaaS requires managing the underlying OS, unlike IaaS"]', 1, 'FaaS platforms typically cap execution duration -- fine for short-lived stateless work, but a hard limiter for anything long-running or stateful.', 'intermediate'),
('cloud', 'cloud-fundamentals', 'intermediate', 'What is described as the biggest lever for real cloud cost optimization that teams frequently skip?', '["Buying the most expensive instance type available", "Right-sizing -- matching instance/resource size to actual observed usage, since a meaningful fraction of real cloud spend is genuinely idle or over-provisioned capacity nobody revisits", "Disabling all monitoring to reduce operational overhead", "Avoiding cloud entirely in favor of on-premise infrastructure"]', 1, 'Right-sizing based on actual observed usage is called out specifically because a meaningful share of real cloud spend is capacity nobody goes back to check and adjust.', 'beginner'),

-- ---------- cloud/multi-cloud/overview ----------
('cloud', 'multi-cloud', 'overview', 'What is described as the single most common, real mistake driving bad multi-cloud adoption decisions?', '["Choosing a regulatory-compliant provider", "Adopting multi-cloud purely as generic \\"just in case\\" risk hedging, with no specific, nameable driver", "Using Terraform to manage more than one cloud", "Running Kubernetes on more than one cloud provider"]', 1, 'The content is explicit that a defensible multi-cloud decision should be able to name a specific risk or requirement -- generic resilience hedging trades a certain ongoing cost for a speculative benefit.', 'intermediate'),
('cloud', 'multi-cloud', 'overview', 'Between "Primary + DR" and "Active/active" multi-cloud patterns, which is generally lower complexity and why?', '["Active/active, because it requires no failover automation at all", "Primary + DR, because only one cloud serves live production traffic while the second is a standby -- active/active requires both clouds to serve live traffic simultaneously behind a global load balancer, which is far more complex", "They are equally complex in every respect", "Primary + DR requires two full production deployments running simultaneously, same as active/active"]', 1, 'Primary + DR keeps one cloud as a standby, which is meaningfully simpler than active/active''s requirement that both clouds serve live traffic and stay in sync.', 'intermediate'),
('cloud', 'multi-cloud', 'overview', 'What does Crossplane add on top of what Kubernetes alone provides for multi-cloud?', '["Crossplane replaces Kubernetes entirely with a simpler API", "Crossplane extends Kubernetes to provision actual cloud resources (databases, queues) using Kubernetes-native YAML, through the same GitOps/reconciliation model used for application workloads", "Crossplane is only usable for observability, not resource provisioning", "Crossplane eliminates the need for Terraform entirely on every cloud"]', 1, 'Crossplane lets infrastructure provisioning use the same K8s-native, GitOps-driven model already used for deploying applications, rather than a separate IaC tool.', 'advanced'),
('cloud', 'multi-cloud', 'overview', 'Why does a leaked one-hour figure like data egress cost between clouds matter operationally?', '["Because data transfer between different cloud providers is billed and can be a real, easy-to-underestimate recurring cost that doesn''t apply to same-provider traffic", "Because egress fees only apply within a single cloud provider''s own region", "Because egress costs are always waived for multi-cloud architectures", "Because egress cost is a one-time fee, never a recurring one"]', 0, 'Moving data between providers incurs real, often underestimated per-GB charges -- worth modeling explicitly before committing to a cross-cloud data flow pattern.', 'intermediate'),
('cloud', 'multi-cloud', 'overview', 'What is the recommended first question to ask when a team proposes multi-cloud "for resilience"?', '["What is the current stock price of each cloud provider?", "What is the specific business driver -- is there a named regulatory requirement, a specific best-of-breed service gap, or a genuine critical-dependency risk?", "Which cloud provider has the most employees?", "How many total engineers work at each cloud provider?"]', 1, 'If there''s no clear driver, the content recommends single cloud first; multi-cloud should be designed for a specific, named need, not adopted reflexively.', 'beginner'),

-- ---------- cloud/multi-cloud/fundamentals ----------
('cloud', 'multi-cloud', 'fundamentals', 'What is the practical significance of Terraform "abstracting the API, not the platform" for multi-cloud IaC?', '["Terraform makes every cloud''s resources behave identically underneath", "The Terraform workflow (plan/apply, state, modules) is shared across providers, but each resource type (aws_instance vs. azurerm_linux_virtual_machine) is still fully cloud-specific underneath", "Terraform eliminates the need to know anything about the underlying cloud provider", "Terraform can only manage one cloud provider per state file, ever"]', 1, 'One Terraform codebase can target multiple providers via separate provider blocks, but the actual resource types and their required arguments remain specific to each cloud.', 'intermediate'),
('cloud', 'multi-cloud', 'fundamentals', 'What does an ArgoCD ApplicationSet with a "clusters" generator accomplish for multi-cluster Kubernetes deployments?', '["It deploys a completely different application to each cluster with no shared source", "It generates one ArgoCD Application per target cluster from a single template, so a change to the manifest source deploys to every registered cluster automatically", "It only works within a single cloud provider''s clusters, never across providers", "It replaces the need for Kubernetes RBAC entirely"]', 1, 'The clusters generator targets every cluster ArgoCD knows about, letting one template deploy consistently across AKS, EKS, or any other registered cluster.', 'advanced'),
('cloud', 'multi-cloud', 'fundamentals', 'Why is a direct interconnect (AWS Direct Connect + Azure ExpressRoute at a shared co-location) chosen over a VPN tunnel for multi-cloud networking?', '["It is always the cheapest option available", "It bypasses the public internet entirely for lower, more consistent latency and higher bandwidth, at higher cost -- often required for regulated workloads needing predictable performance", "VPN tunnels are not capable of connecting two different cloud providers at all", "Direct interconnects require no physical infrastructure at all"]', 1, 'Direct interconnects trade higher cost and longer setup for bypassing the public internet and its latency/reliability variance -- the standard choice once cross-cloud traffic becomes latency-sensitive or business-critical.', 'advanced'),
('cloud', 'multi-cloud', 'fundamentals', 'Which cost category is specifically called out as a real, ongoing multi-cloud expense that tooling alone (Terraform, Kubernetes) does NOT eliminate?', '["Compute pricing, since all clouds charge identical rates", "Data egress fees for moving data between cloud providers, plus the skills gap of needing genuine expertise across 2-3 clouds", "Storage pricing, since all clouds have identical storage tiers", "None -- cloud-agnostic tooling eliminates all extra multi-cloud costs"]', 1, 'Cloud-agnostic tooling reduces duplicated operational effort, but egress fees and the genuine need for per-cloud expertise remain real, ongoing costs regardless of tooling choice.', 'intermediate'),
('cloud', 'multi-cloud', 'fundamentals', 'What distinguishes a Gateway-type VPC endpoint from an Interface-type endpoint being used in a multi-cloud/AWS networking context?', '["Gateway endpoints are route-table based and free (e.g. for S3/DynamoDB); Interface endpoints create an ENI in your subnet with a small hourly cost, used for most other AWS services", "Interface endpoints are always free; Gateway endpoints always cost money", "Gateway endpoints only work across cloud providers, never within a single AWS account", "There is no functional difference between the two endpoint types"]', 0, 'Gateway endpoints (S3, DynamoDB) route via the route table at no extra charge; Interface endpoints deploy an ENI into your subnet for other services, at a small hourly cost.', 'intermediate'),

-- ---------- cloud/multi-cloud/intermediate ----------
('cloud', 'multi-cloud', 'intermediate', 'Why is Kubernetes described as more genuinely portable across clouds than a cloud-specific compute service like Lambda or Azure Functions?', '["Because Kubernetes manifests deploy to EKS, AKS, or GKE with only minor, provider-specific differences (mostly storage classes and load-balancer annotations), unlike a fundamentally provider-specific serverless service", "Because Lambda and Azure Functions do not actually run any code", "Because Kubernetes is free while Lambda and Azure Functions always cost money", "Because Kubernetes cannot run on any single cloud provider alone"]', 0, 'The workload definition itself transfers across managed Kubernetes offerings in a way a cloud-specific serverless compute service fundamentally does not.', 'intermediate'),
('cloud', 'multi-cloud', 'intermediate', 'What is the practical argument for treating multi-cloud "just in case" as a bad reason, even though it sounds prudent?', '["Because multi-cloud is illegal in most regulatory jurisdictions", "Because it trades a real, ongoing operational cost (two platforms to secure, monitor, and staff) against a hypothetical, unquantified future benefit, when the concern is often better addressed by single-cloud multi-AZ/multi-region design instead", "Because \\"just in case\\" reasoning always leads to lower costs in practice", "Because cloud providers do not allow accounts to use more than one cloud"]', 1, 'The complexity cost of multi-cloud is certain and immediate; the risk it hedges against without a named driver is often speculative -- and single-cloud resilience usually solves the same concern more cheaply.', 'advanced'),
('cloud', 'multi-cloud', 'intermediate', 'What does the "best-of-breed" multi-cloud pattern specifically mean?', '["Running every workload identically on every cloud provider at once", "Using each cloud for what it does best -- e.g. GCP BigQuery for analytics while primary infrastructure runs on Azure/AKS -- because that specific service is genuinely the strongest option, not out of generic vendor-avoidance", "Choosing the cheapest cloud provider for every single workload without exception", "A pattern that requires abstracting all storage and compute behind one identical API"]', 1, 'Best-of-breed is about deliberately routing a specific workload to whichever provider genuinely excels at that specific need, not spreading everything everywhere by default.', 'intermediate'),
('cloud', 'multi-cloud', 'intermediate', 'Why does the standardization-vs-best-of-breed tradeoff favor standardizing on one provider''s native services by default?', '["Because native services are always functionally identical across providers", "Because standardizing gets tighter integration, often lower cost (avoiding cross-cloud egress fees), and lets a team build deep expertise in one platform rather than spreading thin -- worth deviating from only when a capability gap is large enough to matter", "Because standardizing eliminates the need for any IAM configuration", "Because multi-cloud is always cheaper regardless of standardization"]', 1, 'Consistency has real, quantifiable benefits (cost, integration depth, focused expertise); the content frames best-of-breed as worth its complexity cost only for a genuinely large capability gap, not as a default philosophy.', 'advanced'),
('cloud', 'multi-cloud', 'intermediate', 'What specifically makes data egress costs easy to underestimate during initial multi-cloud architecture planning?', '["Egress costs are charged upfront before any data is actually moved", "The cost only becomes visible once real production traffic volume hits it -- the per-GB charge is easy to overlook when modeling an architecture on paper before real usage exists", "Cloud providers do not disclose egress pricing until after a contract is signed", "Egress costs are billed annually rather than monthly, delaying awareness"]', 1, 'The content specifically calls out that this cost is easy to miss in initial planning and only becomes visible once real production traffic volume actually crosses cloud boundaries.', 'intermediate'),

-- ---------- cloud/networking-security/overview ----------
('cloud', 'networking-security', 'overview', 'Per the subnet-tier model described, what belongs in a public subnet?', '["Every resource in the VPC, for simplicity", "Only what genuinely needs to be reached directly from the internet -- e.g. a load balancer or bastion host, not application servers or databases", "Only the database tier, for easy access during debugging", "Nothing; public subnets should always be left completely empty"]', 1, 'The practical rule is that only components genuinely requiring direct internet reachability belong in the public subnet -- application servers and databases sit in more isolated tiers behind it.', 'beginner'),
('cloud', 'networking-security', 'overview', 'What is the key functional difference between a Security Group and a Network ACL?', '["They are functionally identical, just named differently per cloud provider", "Security Groups are stateful (return traffic automatically allowed) and scoped per instance; NACLs are stateless (must explicitly allow both directions) and scoped per subnet", "NACLs are stateful; Security Groups are stateless", "Security Groups can only allow traffic; NACLs can only deny it"]', 1, 'This stateful/stateless, per-instance/per-subnet distinction is the core difference -- and the one most likely to cause confusion for someone new to cloud networking.', 'beginner'),
('cloud', 'networking-security', 'overview', 'What are the three core Zero Trust principles listed in this content?', '["Trust by default, verify occasionally, assume safety", "Verify identity explicitly, least privilege access, assume breach", "Perimeter-only defense, implicit trust for internal traffic, verify only external requests", "Encrypt only sensitive data, trust all internal network traffic, disable logging"]', 1, 'Zero Trust rests on verifying identity explicitly (MFA, device health, location), enforcing least privilege (RBAC, just-in-time access), and assuming breach (segment everything, monitor all traffic).', 'beginner'),
('cloud', 'networking-security', 'overview', 'Why should a resource''s Azure Firewall pricing tier not be treated as a fixed, memorized dollar figure when studying this content?', '["Because Azure Firewall is always free regardless of tier", "Because exact cloud service pricing changes over time and by SKU/region, which is why this content flags it as needing verification against current official pricing rather than asserting a fixed number", "Because Azure Firewall pricing is identical to AWS WAF pricing in every region", "Because pricing figures are irrelevant to any real architecture decision"]', 1, 'Version-, pricing-, and console-specific claims are explicitly flagged as needing verification in this content rather than asserted as fixed facts, since cloud pricing figures change over time.', 'intermediate'),
('cloud', 'networking-security', 'overview', 'What must be true for both storage encryption at rest AND encryption in transit, per the Encryption Checklist?', '["Only one of the two needs to be implemented; they are interchangeable", "Both need explicit configuration -- AES-256 at rest for storage services, and TLS 1.2+ enforced everywhere for data in transit, with secrets stored in a dedicated secrets manager rather than environment variables", "Encryption in transit is unnecessary if the network is already private", "Neither is required if the workload runs entirely within one cloud provider"]', 1, 'The checklist requires both encryption states be explicitly handled, plus secrets stored in a dedicated manager (AWS Secrets Manager/Azure Key Vault) rather than environment variables.', 'beginner'),

-- ---------- cloud/networking-security/fundamentals ----------
('cloud', 'networking-security', 'fundamentals', 'Why can application servers in a private subnet still install packages or call third-party APIs, despite not being directly reachable from the internet?', '["Because private subnets are actually identical to public subnets in every respect", "Because a NAT Gateway allows outbound-only internet access -- the asymmetry of outbound-yes, inbound-no is exactly the security property a private subnet provides", "Because private subnet resources are automatically granted a public IP address", "Because AWS/Azure grant free, unrestricted internet access to every private subnet by default with no gateway needed"]', 1, 'A NAT Gateway routes outbound traffic from private-subnet resources to the internet while blocking any inbound connection initiated from the internet -- exactly the asymmetric protection a private subnet is meant to provide.', 'intermediate'),
('cloud', 'networking-security', 'fundamentals', 'Why does a NACL require an explicit outbound rule for the ephemeral port range even after allowing inbound HTTPS on port 443?', '["NACLs do not actually support outbound rules at all", "NACLs are stateless and have no memory of the inbound connection, so the corresponding response traffic on the client''s ephemeral port must be explicitly allowed outbound, unlike a Security Group''s automatic statefulness", "Ephemeral ports are always blocked by AWS regardless of any rule configuration", "Only Security Groups, never NACLs, can filter based on port number"]', 1, 'Because NACLs are stateless, an inbound allow rule does nothing for the response traffic unless the corresponding outbound ephemeral port range is also explicitly allowed.', 'advanced'),
('cloud', 'networking-security', 'fundamentals', 'Why is assuming a private subnet or VPC boundary is sufficient protection for data in transit considered a real mistake?', '["Because private subnets do not actually exist in any major cloud provider", "Because network segmentation limits WHO can reach a service, while TLS protects the DATA ITSELF even if that segmentation is ever bypassed or misconfigured -- the two are complementary, not substitutes", "Because TLS is only relevant for public-facing traffic, never internal traffic", "Because private subnets automatically encrypt all traffic within them by default"]', 1, 'Skipping TLS for "internal" traffic because of a private network boundary removes a real defense-in-depth layer against a genuinely realistic threat model -- a compromised internal host or a routing misconfiguration.', 'intermediate'),
('cloud', 'networking-security', 'fundamentals', 'Why is a dedicated secrets manager (AWS Secrets Manager, Azure Key Vault) preferred over a plain environment variable for storing a database password?', '["Environment variables are always slower to read than a secrets manager API call", "Secrets are stored encrypted with IAM/RBAC-controlled, auditable access and automatable rotation; an environment variable has no built-in access audit trail and commonly ends up accidentally committed to version control", "Plain environment variables cannot technically hold any string value longer than 8 characters", "Secrets managers are free while environment variables always cost money to use"]', 1, 'The core advantages are encrypted storage, an IAM/RBAC-controlled and auditable access trail, and automatable rotation -- none of which a plain environment variable provides.', 'beginner'),
('cloud', 'networking-security', 'fundamentals', 'Per the "least privilege access" Zero Trust checklist item, what is the recommended starting point for a new IAM role or policy?', '["Start from a broad admin template and remove access later as needed", "Start every new role/policy from zero permissions and add only what''s actually needed, rather than starting broad and trying to remove access later", "Grant every new role full account access by default for convenience", "Skip permission scoping entirely for roles used only in development environments"]', 1, 'Starting from zero and adding only what''s needed is emphasized specifically because starting broad and trying to trim access later reliably gets skipped under time pressure.', 'intermediate'),

-- ---------- cloud/networking-security/intermediate ----------
('cloud', 'networking-security', 'intermediate', 'Why does VPC Peering not scale well as the number of VPCs needing to communicate grows?', '["VPC Peering has a hard limit of exactly 2 VPCs per AWS account", "N VPCs that all need to talk to each other require roughly N-squared/2 individual peering connections, each managed separately -- a peering mesh that''s manageable at 5 VPCs becomes a real operational burden at 20", "VPC Peering connections expire automatically after 24 hours", "VPC Peering only works between VPCs in the same Availability Zone"]', 1, 'The peering-mesh connection count grows roughly quadratically with the number of VPCs, which is exactly the scaling problem Transit Gateway''s hub-spoke model solves.', 'intermediate'),
('cloud', 'networking-security', 'intermediate', 'What is the primary security argument (beyond cost savings) for using VPC Endpoints instead of routing to AWS services through a NAT Gateway?', '["VPC Endpoints are required before any EC2 instance can be launched", "A private subnet with VPC Endpoints for everything it needs and no NAT Gateway at all has literally no path to the public internet -- a meaningfully stronger isolation guarantee than outbound-only via NAT", "VPC Endpoints automatically encrypt all data at rest in S3", "VPC Endpoints eliminate the need for any IAM policy on the accessed service"]', 1, 'Beyond avoiding NAT Gateway data-processing charges, a subnet reaching AWS services purely via VPC Endpoints (no NAT Gateway at all) has no path to the public internet whatsoever.', 'advanced'),
('cloud', 'networking-security', 'intermediate', 'Why can Security Groups and NACLs alone not stop a SQL injection attempt sent over HTTPS?', '["Because Security Groups and NACLs only operate on IP/port, and cannot distinguish a legitimate HTTPS request from a malicious one at that layer -- a WAF is needed to inspect actual request content", "Because SQL injection attacks only occur over unencrypted HTTP, never HTTPS", "Because Security Groups automatically block all HTTPS traffic by default", "Because NACLs can only be applied to database subnets, never web-facing subnets"]', 0, 'Security Groups and NACLs operate purely at the IP/port level and cannot see HTTP request content -- a WAF inspects the actual request and can distinguish malicious patterns that look identical at the network layer.', 'intermediate'),
('cloud', 'networking-security', 'intermediate', 'What kind of visibility do VPC Flow Logs (or NSG Flow Logs) actually capture?', '["Full packet capture, including the complete payload of every request", "Connection metadata -- source/destination IP, port, protocol, accept/reject, byte count -- not the actual packet content", "Only successful connections; rejected connections are never logged", "Application-level HTTP headers and request bodies"]', 1, 'Flow logs capture metadata about connections, not full packet content -- but that metadata alone is enough to detect a meaningful class of real incidents like unexpected subnet-to-subnet traffic or exfiltration-pattern spikes.', 'intermediate'),
('cloud', 'networking-security', 'intermediate', 'When does upgrading from NSG to Azure Firewall become worthwhile, per this content?', '["Immediately, for every Azure environment regardless of requirements", "Specifically when FQDN-based outbound filtering matters -- restricting egress to a named allowlist of domains, which is harder to maintain correctly with IP-based rules alone since many services don''t publish stable IP ranges", "Only when the environment has zero virtual networks configured", "Never; NSGs alone are always sufficient regardless of requirements"]', 1, 'The upgrade is framed as worthwhile specifically for FQDN-based outbound filtering needs -- for simpler IP/port-level control, NSGs alone remain a reasonable, cost-free choice.', 'advanced'),

-- ---------- cloud/networking-security/advanced ----------
('cloud', 'networking-security', 'advanced', 'Under PCI-DSS, what determines whether a system is considered "in scope" for the compliance audit?', '["Only systems that directly store or process card data are ever in scope", "Any system that CAN COMMUNICATE WITH the cardholder-data environment is considered in scope, regardless of whether it actually touches card data itself", "Scope is determined solely by which cloud provider is used", "In-scope status is determined only by the size of the company, not network design"]', 1, 'This is why segmentation quality matters far beyond general security hygiene -- a poorly segmented network where the CDE is broadly reachable pulls unrelated infrastructure into the full audit scope.', 'advanced'),
('cloud', 'networking-security', 'advanced', 'Why does enabling only AWS Shield Standard (or Azure DDoS Protection) leave a real gap in DDoS defense?', '["Because Shield Standard is not actually free and requires a paid subscription", "Because it defends against L3/L4 volumetric floods but cannot distinguish an L7 application-layer flood (many individually legitimate-looking HTTP requests) from real traffic -- that requires a separately configured WAF rate-limiting layer", "Because Shield Standard only protects against attacks originating from a single specific country", "Because Shield Standard requires manual activation before every individual attack"]', 1, 'L7 application-layer floods look like legitimate traffic to L3/L4 protection -- closing this gap requires an explicitly configured WAF rate-limiting layer, which many teams skip after enabling basic DDoS protection.', 'advanced'),
('cloud', 'networking-security', 'advanced', 'For a latency-sensitive, high-volume, business-critical hybrid data path, why would a dedicated connection (Direct Connect/ExpressRoute) be chosen over a site-to-site VPN?', '["Dedicated connections are always cheaper than VPN regardless of traffic volume", "A dedicated connection provides consistent, predictable latency and bandwidth by bypassing the public internet, whereas VPN is subject to public internet latency/reliability variance that becomes a real operational risk at that criticality level", "VPN connections have a hard maximum bandwidth of 1 Mbps", "Dedicated connections require no provisioning lead time, unlike VPN"]', 1, 'The tradeoff is explicit: VPN is fine for lower-stakes, latency-tolerant integrations, but a dedicated connection''s consistency becomes worth its higher cost and longer lead time once the data path is genuinely business-critical.', 'advanced'),
('cloud', 'networking-security', 'advanced', 'What distinguishes "full Zero Trust maturity" from the starting Zero Trust checklist, per the Advanced content?', '["Full maturity means removing MFA requirements to reduce user friction", "Full maturity adds micro-segmentation at the individual workload level, continuous re-authorization (not just point-in-time authentication), and a full audit trail across every access decision -- not just logins", "Full maturity requires abandoning all network segmentation in favor of identity alone", "There is no meaningful difference; the starting checklist already represents full maturity"]', 1, 'The Advanced tab extends the Fundamentals-tab starting checklist into continuous, automated enforcement -- workload-level micro-segmentation, continuous authorization, and comprehensive audit trails.', 'advanced'),
('cloud', 'networking-security', 'advanced', 'Why is "the Security Group must be misconfigured" often the wrong first conclusion when HTTPS traffic to a private-subnet resource fails despite a correct-looking Security Group rule?', '["Because Security Group rules can never actually be the cause of blocked traffic", "Because at least three other equally common causes exist in the path -- a missing route table entry, a NACL blocking one direction (since NACLs are stateless), or the resource''s own OS-level firewall -- and should be checked in order before assuming the Security Group is wrong", "Because Security Groups take up to 24 hours to propagate after being changed", "Because only NACLs, never Security Groups, can actually block traffic"]', 1, 'The systematic troubleshooting order checks the route table, then NACLs (both directions, since they''re stateless), then the Security Group, then the OS-level firewall -- skipping straight to blaming the Security Group misses three other equally common causes.', 'intermediate'),

-- ---------- cloud/cloud-security/overview ----------
('cloud', 'cloud-security', 'overview', 'Under the shared responsibility model, what is "security OF the cloud" versus "security IN the cloud"?', '["They refer to the same set of responsibilities under two different names", "\\"OF the cloud\\" is the provider''s responsibility (physical security, hardware, hypervisor, managed service internals); \\"IN the cloud\\" is the customer''s responsibility (data, IAM, network config, application security)", "\\"IN the cloud\\" refers only to on-premise infrastructure connected to the cloud", "\\"OF the cloud\\" is always the customer''s responsibility regardless of service model"]', 1, 'The provider secures the infrastructure itself; the customer secures everything they configure and put on top of it -- and this boundary shifts by service type (IaaS/PaaS/SaaS) but never disappears entirely for the customer.', 'beginner'),
('cloud', 'cloud-security', 'overview', 'What was the actual root cause of the Capital One 2019 breach, per how this content frames it?', '["A flaw in AWS''s own physical infrastructure that AWS failed to patch", "A misconfigured web application firewall combined with an over-permissive IAM role -- a customer-side configuration issue, not a breach of AWS''s underlying infrastructure", "AWS''s hypervisor being compromised by an external attacker", "A vulnerability in AWS''s S3 durability guarantees"]', 1, 'This is used as the concrete illustration that real cloud security incidents overwhelmingly trace back to customer-side configuration, not provider infrastructure failures.', 'intermediate'),
('cloud', 'cloud-security', 'overview', 'Which of these is listed among the "Top Cloud Security Misconfigurations" in this content?', '["Using a managed Kubernetes service instead of self-hosting", "Overly permissive IAM policies, such as AdministratorAccess granted to all users", "Enabling GuardDuty/Defender for Cloud/SCC in every region", "Rotating access keys more frequently than every 90 days"]', 1, 'AdministratorAccess granted broadly is explicitly listed as one of the top real-world misconfigurations, alongside public storage buckets, missing MFA on root, and open security groups.', 'beginner'),
('cloud', 'cloud-security', 'overview', 'What does "the boundary shifts by service type" mean in the context of the shared responsibility model?', '["The provider is responsible for everything once a service becomes PaaS or SaaS", "For IaaS, the customer manages the OS upward; for PaaS, the customer manages application and data; for SaaS, the customer manages data and user access only -- less customer scope moving up the stack, but never zero", "The customer is responsible for physical hardware security regardless of service type", "The boundary is identical and fixed across IaaS, PaaS, and SaaS"]', 1, 'Customer responsibility shrinks as you move from IaaS to SaaS, but it never fully disappears -- data, access, and configuration decisions remain the customer''s at every layer.', 'intermediate'),
('cloud', 'cloud-security', 'overview', 'Why is traditional, perimeter-based security described as insufficient in cloud environments?', '["Because cloud environments have no network boundaries of any kind", "Because cloud environments are identity-centric and API-driven with dynamic infrastructure -- a single perimeter wall/gate model doesn''t fit an environment where every resource can be created or reached via an API call from anywhere", "Because perimeter security is more expensive to implement in the cloud than on-premise", "Because cloud providers actively disable all perimeter security controls by policy"]', 1, 'The dynamic, API-driven, identity-centric nature of cloud infrastructure is why identity, not a network perimeter, has to become the primary control -- there is no single gate to defend.', 'intermediate'),

-- ---------- cloud/cloud-security/fundamentals ----------
('cloud', 'cloud-security', 'fundamentals', 'Why is a leaked root/admin access key with no MFA considered a worse incident than a typical application bug?', '["Because application bugs are always more expensive to fix than a leaked credential", "Because an application bug is scoped to what that application can touch, while a leaked root-equivalent credential is scoped to everything in the account, including the ability to create new admin users to maintain persistent access", "Because leaked credentials are always publicly disclosed immediately, unlike application bugs", "Because application bugs cannot be fixed once deployed to production"]', 1, 'The blast radius is the key distinction -- a root-equivalent leaked credential can touch the entire account, including creating new privileged access that persists even after the original key is revoked.', 'beginner'),
('cloud', 'cloud-security', 'fundamentals', 'What does IAM Access Analyzer specifically help identify?', '["The exact dollar cost of every IAM policy in an account", "Unintended external access -- resources that are accessible from outside the account or organization that shouldn''t be", "Which EC2 instances are currently running", "The physical AWS region closest to the customer"]', 1, 'Access Analyzer is used specifically to surface resources with unintended external access, a common and serious real-world misconfiguration class.', 'intermediate'),
('cloud', 'cloud-security', 'fundamentals', 'Why is `--enable-log-file-validation` on a CloudTrail trail described as useful?', '["It makes CloudTrail logging free instead of a paid feature", "It helps detect tampering with the logs themselves -- an important property for an audit trail that needs to be trustworthy even if an attacker gains some level of access", "It automatically deletes old log files after 30 days to save storage costs", "It disables logging for any account with root-level access"]', 1, 'Log file validation is specifically about detecting tampering -- ensuring the audit trail itself can be trusted even in a scenario where an attacker has gained some access.', 'advanced'),
('cloud', 'cloud-security', 'fundamentals', 'What is the security benefit of an S3 bucket policy that denies requests where `aws:SecureTransport` is false?', '["It blocks all access to the bucket entirely, including legitimate access", "It enforces that all requests to the bucket must use TLS/HTTPS, denying any request made over an unencrypted connection", "It automatically compresses all objects stored in the bucket", "It grants public read access to every object in the bucket"]', 1, 'This condition-based deny policy is the mechanism for enforcing encryption in transit specifically for S3 -- rejecting any request not made over a secure (HTTPS) connection.', 'intermediate'),
('cloud', 'cloud-security', 'fundamentals', 'Why does this content recommend using IAM roles for services rather than long-term access keys for humans?', '["Because IAM roles are always faster to provision than access keys", "Because long-term access keys are static, storable, and leakable credentials that persist until manually rotated or revoked, while roles provide temporary, auto-managed credentials", "Because AWS charges extra for using long-term access keys", "Because long-term access keys cannot be used with any AWS service"]', 1, 'This mirrors the general principle of preferring temporary, auto-rotated credentials (roles) over long-lived stored secrets (access keys), which reduces the impact of a leak.', 'beginner'),

-- ---------- cloud/cloud-security/intermediate ----------
('cloud', 'cloud-security', 'intermediate', 'What is a Permission Boundary used for in IAM?', '["It grants additional permissions beyond what a policy already allows", "It limits the maximum permissions an IAM entity can have -- even if an attached policy grants a wildcard (*), the boundary restricts effective access to only what the boundary itself permits", "It is only usable for S3 bucket policies, not IAM entities", "It automatically expires all IAM roles after 90 days"]', 1, 'A Permission Boundary acts as a ceiling, not a grant -- useful for safely delegating IAM policy creation to development teams without risking over-broad effective access.', 'advanced'),
('cloud', 'cloud-security', 'intermediate', 'Why is referencing Security Groups by ID, rather than by IP range, recommended as a best practice?', '["Because Security Group IDs are shorter and easier to type", "Because IP addresses can be dynamic, while referencing another Security Group by ID stays correct even as the underlying instances'' IPs change", "Because AWS does not allow IP-based rules in Security Groups at all", "Because Security Group IDs automatically update DNS records"]', 1, 'Referencing by Security Group ID avoids the maintenance burden and potential staleness of hardcoded IP ranges as instances are replaced and IPs change.', 'intermediate'),
('cloud', 'cloud-security', 'intermediate', 'What is the specific advantage of AWS Systems Manager Session Manager over a traditional bastion host for administrative access?', '["Session Manager requires a public IP on every target instance", "It requires no SSH key management and no open inbound ports on the target instance, with all sessions logged to CloudWatch/S3", "Session Manager can only be used for Windows instances, never Linux", "It eliminates the need for any IAM permissions to access an instance"]', 1, 'Session Manager removes the SSH key management burden and the open-inbound-port attack surface a traditional bastion host requires, while providing a full session audit log.', 'intermediate'),
('cloud', 'cloud-security', 'intermediate', 'Why does VPC Flow Logs configuration specifically call out capturing REJECT traffic as valuable?', '["Because reject events are the only traffic type that consumes storage cost", "Because rejected connection attempts are a strong signal for detecting scanning activity or misconfigured/blocked legitimate traffic -- accepted traffic alone misses this visibility", "Because AWS only bills for logging accepted traffic, making REJECT logging free", "Because reject events are required before Security Groups can be created"]', 1, 'Rejected traffic is specifically valuable for forensics and threat detection -- it surfaces both potential scanning/attack activity and legitimate traffic that''s unexpectedly being blocked.', 'advanced'),
('cloud', 'cloud-security', 'intermediate', 'What does the AWS condition key `aws:MultiFactorAuthPresent` combined with `BoolIfExists` and a Deny effect accomplish?', '["It permanently disables MFA for all IAM users in the account", "It denies an action if MFA was not present at the time of the request, effectively requiring MFA for that action to succeed", "It automatically enables MFA on every new IAM user by default", "It only applies to root account actions, never IAM user actions"]', 1, 'This is a standard pattern for enforcing MFA at the policy level -- denying the requested action whenever the MFA condition is not satisfied.', 'advanced'),

-- ---------- cloud/cloud-security/advanced ----------
('cloud', 'cloud-security', 'advanced', 'What is the core principle behind Zero Trust''s "assume breach" approach?', '["Assume that no attacker will ever successfully compromise any part of the system", "Design systems assuming an adversary is already inside, which drives practices like micro-segmentation and comprehensive monitoring rather than relying on perimeter defense alone", "Disable all logging to reduce the chance of leaking sensitive audit data", "Assume breach only applies to on-premise systems, never cloud systems"]', 1, '"Assume breach" is a design posture, not a prediction -- it drives building in segmentation and visibility so a breach, when it happens, is contained and detectable rather than catastrophic.', 'intermediate'),
('cloud', 'cloud-security', 'advanced', 'In a DevSecOps pipeline, what is the specific difference between SAST and DAST?', '["They are two names for the exact same scanning technique", "SAST (Static Application Security Testing) scans source code; DAST (Dynamic Application Security Testing) scans the running application", "DAST only works on infrastructure-as-code files, never applications", "SAST can only run after an application is deployed to production"]', 1, 'SAST analyzes source code statically before runtime; DAST tests the actual running application, catching a different class of issues than static analysis alone.', 'intermediate'),
('cloud', 'cloud-security', 'advanced', 'Why is running a container as a non-root user, with a read-only filesystem, considered a meaningful container security practice?', '["Because it makes the container image smaller in file size", "Because it reduces what an attacker who compromises the container process can actually do -- limiting write access and privilege reduces the practical impact of a container-level compromise", "Because non-root containers start up faster than root containers", "Because Kubernetes requires all containers to run as non-root by policy default"]', 1, 'Minimizing what a compromised container process can modify or escalate to is a defense-in-depth measure that reduces the practical impact if a container is compromised.', 'intermediate'),
('cloud', 'cloud-security', 'advanced', 'During incident containment for a compromised IAM key, what is the first recommended action per this content?', '["Immediately delete the entire AWS account", "Disable the access key immediately and attach a deny-all policy to the affected user", "Wait for a scheduled maintenance window before taking any action", "Rotate every other unrelated IAM user''s credentials in the account first"]', 1, 'The immediate containment step for a compromised IAM key is disabling it and locking down the associated user, before moving to eradication and recovery steps.', 'intermediate'),
('cloud', 'cloud-security', 'advanced', 'Why does full Zero Trust maturity require "continuous authorization" rather than relying on authentication alone?', '["Because authentication tokens never expire on their own in any cloud platform", "Because a session authenticated an hour ago should be re-evaluated against current context (device health, anomalous access patterns) rather than trusted indefinitely until token expiry", "Because continuous authorization eliminates the need for MFA entirely", "Because authentication and authorization are the exact same mechanism"]', 1, 'Point-in-time authentication doesn''t account for context changing after the fact -- continuous authorization re-evaluates trust as conditions change, not just at initial login.', 'advanced')

ON CONFLICT (academy_slug, technology_slug, section_slug, question) DO NOTHING;
